//! Sys Loot over actual selected CODE_MAPS raw loans; returned data is unsealed.
use crate::{captured_generator_budget::Budget,captured_raw_file::{Config,RawPolicyViews},reactive_raw_policy_pages::RawPolicyPages,reactive_reads_native::Failure,captured_allow_annotations::PatternOperation,key_policy_control::{self as kc,Control},lint::{Site,AllowUse}};
use std::{io,sync::Arc,collections::{HashSet,BTreeMap}};
pub fn metadata()->&'static crate::lint::Meta{static META:std::sync::OnceLock<crate::lint::Meta>=std::sync::OnceLock::new();META.get_or_init(||crate::dm::sys::module_metadata(&crate::dm::sys::SysModule{name:"loot",rules:crate::sys_loot_policy::RULES,..crate::dm::sys::SysModule::DEFAULT},crate::lint::ScanKind::Tree))}
pub struct LootData{sites:Vec<Site>,source_text:Vec<String>,allow_used:Vec<AllowUse>,allow_digests:BTreeMap<String,[u8;20]>}
impl LootData{pub fn sites(&self)->&[Site]{&self.sites}pub fn source_text(&self)->&[String]{&self.source_text}pub fn allow_used(&self)->&[AllowUse]{&self.allow_used}pub fn allow_source_digest(&self,relative:&str)->Option<&[u8;20]>{self.allow_digests.get(relative)}pub fn retained_charge(&self)->Option<usize>{let mut n=std::mem::size_of::<Self>().checked_add(self.sites.capacity().checked_mul(std::mem::size_of::<Site>())?)?.checked_add(self.source_text.capacity().checked_mul(std::mem::size_of::<String>())?)?.checked_add(self.allow_used.capacity().checked_mul(std::mem::size_of::<AllowUse>())?)?;for site in &self.sites{for word in [&site.rule,&site.rel,&site.msg,&site.key,&site.ident]{n=n.checked_add(word.capacity())?;}}for word in &self.source_text{n=n.checked_add(word.capacity())?;}for value in &self.allow_used{n=n.checked_add(value.rel.capacity())?.checked_add(value.name.capacity())?.checked_add(value.code.capacity())?;}for(name,_)in &self.allow_digests{n=n.checked_add(2048)?.checked_add(name.capacity())?;}Some(n)}}
fn oom(b:&Budget,message:impl Into<String>)->Failure{b.deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message.into()))}
fn checked(b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<(),Failure>{b.require().map_err(|m|oom(b,m))?;poll()?;b.require().map_err(|m|oom(b,m))}
fn finish<T>(pending:Result<T,Failure>,b:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<T,Failure>{if matches!(&pending,Err(Failure::Operational(_))){return pending}checked(b,poll)?;pending}
struct Phase{budget:Arc<Budget>,ok:bool}impl Drop for Phase{fn drop(&mut self){if !self.ok{self.budget.keep_failed_scratch()}}}
fn row<T>(c:&mut PatternOperation<'_>,rows:&mut Vec<T>)->Result<(),Failure>{if rows.len()<rows.capacity(){return Ok(())}let target=rows.capacity().checked_mul(2).map(|n|n.max(4)).ok_or_else(||c.overflow())?;let bound=target.checked_mul(4).ok_or_else(||c.overflow())?;kc::reserve(c,||bound.checked_mul(std::mem::size_of::<T>())?.checked_add(128))?;rows.try_reserve_exact(target-rows.len()).map_err(|_|c.allocation_failed())?;if rows.capacity()>bound{return Err(c.allocation_failed())}Ok(())}
fn add_file(views:RawPolicyViews<'_>,roots:&HashSet<String>,out:&mut LootData,keep:&Budget,poll:&dyn Fn()->io::Result<()>,patterns:Option<&dyn crate::native_pattern::Provider>)->Result<(),Failure>{let local=views.allocation_budget(keep);let pending=(||{let f=views.source_file()?;let mut temporary=PatternOperation{patterns,budget:local,poll};let mut persistent=PatternOperation{patterns,budget:keep,poll};let mut found=Vec::new();crate::sys_loot_policy::judge_using(f,roots,&mut found,&mut temporary)?;let mut used=false;for(rule,line)in found{temporary.checkpoint()?;let allow_name=kc::format(&mut temporary,format_args!("sys_{rule}"))?;if let Some(kept)=crate::allow::kept_using(f,line,&allow_name,&mut temporary)?{let code=kept.code.unwrap_or_default();let value=AllowUse{rel:kc::own(&mut persistent,&f.rel)?,line:u32::try_from(kept.line).map_err(|_|persistent.overflow())?,name:kc::own(&mut persistent,&allow_name)?,code};persistent.reserve(value.code.capacity())?;if !out.allow_used.contains(&value){row(&mut persistent,&mut out.allow_used)?;out.allow_used.push(value);}used=true;continue}row(&mut persistent,&mut out.sites)?;row(&mut persistent,&mut out.source_text)?;out.sites.push(Site{rule:kc::own(&mut persistent,rule)?,rel:kc::own(&mut persistent,&f.rel)?,line:u32::try_from(line).map_err(|_|persistent.overflow())?,msg:String::new(),key:String::new(),ident:String::new()});let raw=f.raw();let original=if line>0&&line<=raw.num_lines(){raw.line(line)}else{""};let words=original.split_whitespace().try_fold(0usize,|n,_|{temporary.checkpoint()?;n.checked_add(1).ok_or_else(||temporary.overflow())})?;kc::reserve(&mut temporary,||words.checked_mul(4*std::mem::size_of::<&str>())?.checked_add(original.len().checked_mul(4)?)?.checked_add(256))?;let text=crate::util::normalize_ws(original);persistent.reserve(text.capacity())?;out.source_text.push(text);}if used&&!out.allow_digests.contains_key(&f.rel){kc::reserve(&mut persistent,||Some(2048+std::mem::size_of::<(String,[u8;20])>()))?;out.allow_digests.insert(kc::own(&mut persistent,&f.rel)?,crate::captured_raw_file::source_allow_digest(f));}Ok(())})();finish(pending,local,poll)}
pub fn collect<P:RawPolicyPages+?Sized>(pages:&P,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<LootData,Failure>{collect_using(pages,config,root,poll,None)}
pub fn collect_with_patterns<P:RawPolicyPages+?Sized>(pages:&P,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,patterns:&dyn crate::native_pattern::Provider)->Result<LootData,Failure>{collect_using(pages,config,root,poll,Some(patterns))}
fn collect_using<P:RawPolicyPages+?Sized>(pages:&P,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,patterns:Option<&dyn crate::native_pattern::Provider>)->Result<LootData,Failure>{checked(root,poll)?;let mut phase=Phase{budget:Budget::scoped_temporaries(root).map_err(|m|oom(root,m))?,ok:false};let keep=&phase.budget;let pending=(||{let mut work=PatternOperation{patterns,budget:keep,poll};let selected=|relative:&str|crate::dm::sys::policy_selection().matches_path(relative)&&!config.policy_path_exempt("sys/loot","sys",relative);let mut roots=HashSet::new();kc::reserve(&mut work,||Some(2048))?;roots.insert(kc::own(&mut work,"/obj/random")?);let complete=pages.for_each(&mut|relative,views|{let local=views.allocation_budget(keep);let pending=(||{checked(local,poll)?;if !selected(relative){return Ok(true)}let f=views.source_file()?;if f.rel!=relative{return Err("Loot original file label differs".into())}let mut temporary=PatternOperation{patterns,budget:local,poll};for name in crate::sys_loot_policy::roots_of_using(f,&mut temporary)?{work.checkpoint()?;if !roots.contains(&name){kc::reserve(&mut work,||Some(2048))?;work.reserve(name.capacity())?;roots.insert(name);}}Ok(true)})();finish(pending,local,poll)})?;if !complete{return Err("Loot root source stopped before actual selected EOF".into())}let mut output=LootData{sites:Vec::new(),source_text:Vec::new(),allow_used:Vec::new(),allow_digests:BTreeMap::new()};let complete=pages.for_each(&mut|relative,views|{checked(keep,poll)?;if !selected(relative){return Ok(true)}if views.source_file()?.rel!=relative{return Err("Loot original source label differs".into())}add_file(views,&roots,&mut output,keep,poll,patterns)?;Ok(true)})?;if !complete{return Err("Loot judgment source stopped before actual selected EOF".into())}checked(keep,poll)?;Ok(output)})();let pending=finish(pending,keep,poll);let pending=match pending{Ok(data)=>{let bytes=data.retained_charge().ok_or_else(||oom(root,"Loot returned capacity overflow"))?;match root.charge(bytes).map_err(|m|oom(root,m)){Ok(())=>Ok(data),Err(actual)=>{drop(data);Err(actual)}}},Err(actual)=>Err(actual)};phase.ok=pending.is_ok();drop(phase);finish(pending,root,poll)}
